import { ResponseError } from "../../errors.js";
import { Writer } from "../../protocol/writer.js";
import { createAPI } from "../definitions.js";
/*
  AlterClientQuotas Request (Version: 0) => [entries] validate_only
    entries => [entity] [ops]
      entity => entity_type entity_name
        entity_type => STRING
        entity_name => NULLABLE_STRING
      ops => key value remove
        key => STRING
        value => FLOAT64
        remove => BOOLEAN
    validate_only => BOOLEAN
*/
export function createRequest(entries, validateOnly) {
    return Writer.create()
        .appendArray(entries, (w, entry) => {
        w.appendArray(entry.entities, (w, entity) => {
            w.appendString(entity.entityType, false).appendString(entity.entityName, false);
        }, false, false).appendArray(entry.ops, (w, op) => {
            w.appendString(op.key, false)
                .appendFloat64(op.value ?? 0)
                .appendBoolean(op.remove);
        }, false, false);
    }, false, false)
        .appendBoolean(validateOnly);
}
/*
  AlterClientQuotas Response (Version: 0) => throttle_time_ms [entries]
    throttle_time_ms => INT32
    entries => error_code error_message [entity]
      error_code => INT16
      error_message => NULLABLE_STRING
      entity => entity_type entity_name
        entity_type => STRING
        entity_name => NULLABLE_STRING
*/
export function parseResponse(_correlationId, apiKey, apiVersion, reader) {
    const errors = [];
    const response = {
        throttleTimeMs: reader.readInt32(),
        entries: reader.readArray((r, index) => {
            const entry = {
                errorCode: r.readInt16(),
                errorMessage: r.readNullableString(false),
                entity: r.readArray(r => ({ entityType: r.readString(false), entityName: r.readNullableString(false) }), false, false)
            };
            if (entry.errorCode !== 0) {
                errors.push([`/entries/${index}`, [entry.errorCode, entry.errorMessage]]);
            }
            return entry;
        }, false, false)
    };
    if (errors.length) {
        throw new ResponseError(apiKey, apiVersion, Object.fromEntries(errors), response);
    }
    return response;
}
export const api = createAPI(49, 0, createRequest, parseResponse, false, false);
